// Do not edit this file as it will be overwritten if codegen is rerun

use data::*;

macro_rules! implies {
  ($lhs: expr, $rhs: expr) => {
    !$lhs || $rhs
  };
}

macro_rules! impliesL {
  ($lhs: expr, $rhs: expr) => {
    !$lhs | $rhs
  };
}

pub fn IS_ZEROIZED(logs: Common::LogArray_Impl) -> bool
{
  (0..=logs.len() - 1).all(|i| (logs[i].timestamp == 0u32) &
    (logs[i].userID == 0u32) &
    (logs[i].numSuspects == 0u32) &
    (logs[i].numSuspectsFlagged == 0u32) &
    (logs[i].yaw == 0i32) &
    (logs[i].pitch == 0i32) &
    (logs[i].roll == 0i32))
}

/** Initialize EntryPointContract
  *
  * guarantee defaultZeroize
  * @param zeroize_cmd post-state state variable
  */
pub fn initialize_defaultZeroize(zeroize_cmd: bool) -> bool
{
  zeroize_cmd == false
}

/** IEP-Guar: Initialize Entrypoint for dataManager
  *
  * @param cache post-state state variable
  * @param zeroize_cmd post-state state variable
  * @param api_response_log outgoing event data port
  */
pub fn initialize_IEP_Guar(
  cache: Common::LogArray_Impl,
  zeroize_cmd: bool,
  api_response_log: Option<Common::ResponseLog_Impl>) -> bool
{
  initialize_defaultZeroize(zeroize_cmd)
}

/** IEP-Post: Initialize Entrypoint Post-Condition
  *
  * @param cache post-state state variable
  * @param zeroize_cmd post-state state variable
  * @param api_response_log outgoing event data port
  */
pub fn initialize_IEP_Post(
  cache: Common::LogArray_Impl,
  zeroize_cmd: bool,
  api_response_log: Option<Common::ResponseLog_Impl>) -> bool
{
  initialize_IEP_Guar(cache, zeroize_cmd, api_response_log)
}

/** Compute Entrypoint Contract
  *
  * guarantee zeroize_cmd_variable
  *   G: Once a zeroize command is seen, always zeroize.
  * @param In_zeroize_cmd pre-state state variable
  * @param zeroize_cmd post-state state variable
  * @param api_zeroize incoming event port
  */
pub fn compute_spec_zeroize_cmd_variable_guarantee(
  In_zeroize_cmd: bool,
  zeroize_cmd: bool,
  api_zeroize: Option<u8>) -> bool
{
  (impliesL!(
    api_zeroize.is_some(),
    (zeroize_cmd == true))) &
    (impliesL!(
      (In_zeroize_cmd == true),
      (zeroize_cmd == true)))
}

/** Compute Entrypoint Contract
  *
  * guarantee Zeroize_Payload
  *   G: Zeroize outgoing responses once an alert is received and when a request has been made.
  * @param zeroize_cmd post-state state variable
  * @param api_request_log incoming event data port
  * @param api_response_log outgoing event data port
  */
pub fn compute_spec_Zeroize_Payload_guarantee(
  zeroize_cmd: bool,
  api_request_log: Option<Common::Request_Impl>,
  api_response_log: Option<Common::ResponseLog_Impl>) -> bool
{
  impliesL!(
    zeroize_cmd & api_request_log.is_some(),
    IS_ZEROIZED(api_response_log.unwrap().payload))
}

/** Compute Entrypoint Contract
  *
  * guarantee Zeroize_Cache
  *   G: Zeroize cache once an alert is received.
  * @param cache post-state state variable
  * @param zeroize_cmd post-state state variable
  */
pub fn compute_spec_Zeroize_Cache_guarantee(
  cache: Common::LogArray_Impl,
  zeroize_cmd: bool) -> bool
{
  impliesL!(
    zeroize_cmd,
    IS_ZEROIZED(cache))
}

/** CEP-T-Guar: Top-level guarantee contracts for dataManager's compute entrypoint
  *
  * @param In_zeroize_cmd pre-state state variable
  * @param cache post-state state variable
  * @param zeroize_cmd post-state state variable
  * @param api_zeroize incoming event port
  * @param api_request_log incoming event data port
  * @param api_response_log outgoing event data port
  */
pub fn compute_CEP_T_Guar(
  In_zeroize_cmd: bool,
  cache: Common::LogArray_Impl,
  zeroize_cmd: bool,
  api_zeroize: Option<u8>,
  api_request_log: Option<Common::Request_Impl>,
  api_response_log: Option<Common::ResponseLog_Impl>) -> bool
{
  let r0: bool = compute_spec_zeroize_cmd_variable_guarantee(In_zeroize_cmd, zeroize_cmd, api_zeroize);
  let r1: bool = compute_spec_Zeroize_Payload_guarantee(zeroize_cmd, api_request_log, api_response_log);
  let r2: bool = compute_spec_Zeroize_Cache_guarantee(cache, zeroize_cmd);

  return r0 && r1 && r2;
}

/** CEP-Post: Compute Entrypoint Post-Condition for dataManager
  *
  * @param In_cache pre-state state variable
  * @param In_zeroize_cmd pre-state state variable
  * @param cache post-state state variable
  * @param zeroize_cmd post-state state variable
  * @param api_zeroize incoming event port
  * @param api_HMD_log incoming event data port
  * @param api_request_log incoming event data port
  * @param api_response_log outgoing event data port
  */
pub fn compute_CEP_Post(
  In_cache: Common::LogArray_Impl,
  In_zeroize_cmd: bool,
  cache: Common::LogArray_Impl,
  zeroize_cmd: bool,
  api_zeroize: Option<u8>,
  api_HMD_log: Option<Common::Log_Impl>,
  api_request_log: Option<Common::Request_Impl>,
  api_response_log: Option<Common::ResponseLog_Impl>) -> bool
{
  // CEP-Guar: guarantee clauses of dataManager's compute entrypoint
  let r0: bool = compute_CEP_T_Guar(In_zeroize_cmd, cache, zeroize_cmd, api_zeroize, api_request_log, api_response_log);

  return r0;
}
